def load_registration(protocol=PROTOCOL,corpus=None,init_weights=None):
    need(Path(protocol).resolve()==PROTOCOL.resolve(),'unregistered protocol')
    p=read_json(protocol); content=p.pop('content_sha256')
    need(parent.json_hash(p)==content,'registration hash drift');p['content_sha256']=content
    need(sha256(STAGE/'soft-parent-manifest.json')=='958147cf1848222c23d1444f3c5848ba7a5e27026aeb38eba82cc4ccaedcbd48','soft parent registration drift')
    base=read_json(STAGE/'soft-parent-manifest.json')
    need(sha256(STAGE/'exp143v2-manifest.json')=='b2aaca64289249595e532b74d361175ed78b1170109eee302ec29068e0e7af11','EXP143v2 manifest identity drift')
    exp=read_json(STAGE/'exp143v2-manifest.json')
    expected=dict(base)
    for key in ('train_ids','excluded_gold_ids','train_labels','pos_weight','label_sha256',
                'label_provenance_sha256','label_provenance','label_file_name'):
        expected[key]=exp[key]
    expected.update(schema='hb156-convnext-l2-s42/v1',version='2.0.0',
                    run_dirs={'local':'stage-convnext-l2-s42-v1/S42'})
    expected['source_bindings']=p['source_bindings']
    expected['content_sha256']=p['content_sha256']
    need(set(p['source_bindings'])==set(base['source_bindings'])|{'tools/hb156_package_v2.py'},'source binding roster drift')
    for name,digest in base['source_bindings'].items():
        if name not in ('tools/hb156_vast_v1.py','run.sh'):
            need(p['source_bindings'][name]==digest,'unchanged source binding drift: '+name)
    need(p['recipe']==base['recipe'],'only L2 label recipe delta allowed')
    need(p['decision']==base['decision']==read_json(STAGE/'decision.json'),'decision drift')
    need(p==expected,'non-allowlisted L2 registration change')
    for name,digest in p['source_bindings'].items(): need(sha256(ROOT/name)==digest,'source drift: '+name)
    need(sha256(STAGE/'seed42-manifest.json')==p['seed42_manifest_sha256'],'seed42 registration drift')
    need(sha256(STAGE/exp['label_file_name'])=='79ce307e246cc54a9a90f32fd1ab21d58ebd23b4b7e7b1a80207adcea1bcc2c9'==p['label_sha256'],
         'exact EXP143v2 L2 label file required; soft-label substitute refused')
    need(sha256(STAGE/'label-provenance.json')==p['label_provenance_sha256'],'L2 provenance drift')
    rows=parent.read_label_table(STAGE/exp['label_file_name'])
    selected={uid:rows[uid] for uid in p['train_ids']}
    need(selected==p['train_labels'] and not set(selected)&set(p['excluded_gold_ids']),'labels/Gold roster drift')
    need(parent.pos_weights(selected,p['train_ids'])==p['pos_weight'],'EXP143v2 pos_weight policy drift')
    if corpus is not None:
        need(Path(corpus).resolve()==CORPUS.resolve(),'wrong cache path')
        need(sha256(CORPUS/'manifest.json')==p['corpus_manifest_sha256'] and
             sha256(CORPUS/'build-registration.json')==p['corpus_build_sha256'],'cache receipts drift')
    if init_weights is not None:
        need(Path(init_weights).resolve()==INIT.resolve() and sha256(INIT)==p['init_sha256'],'init drift')
    verify_trainer()
    return p


